BEGIN;
--
-- Create model Categoria
--
CREATE TABLE "AppStoreLink_categoria" (
    "id_categoria" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, 
    "tipo_categoria" varchar(20) NOT NULL
);
--
-- Create model Endereco
--
CREATE TABLE "AppStoreLink_endereco" (
    "id_endereco" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, 
    "rua" varchar(100) NOT NULL, 
    "numero_estabelecimento" varchar(10) NOT NULL, 
    "cep" varchar(9) NOT NULL
);
--
-- Create model TipoUsuario
--
CREATE TABLE "AppStoreLink_tipousuario" (
    "id_tipo_usuario" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, 
    "tipo_usuario" varchar(12) NOT NULL
);
--
-- Create model Loja
--
CREATE TABLE "AppStoreLink_loja" (
    "id_loja" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, 
    "nome_loja" varchar(100) NOT NULL, 
    "categoria" varchar(50) NULL, 
    "telefone_loja" varchar(15) NULL, 
    "email_loja" varchar(100) NOT NULL, 
    "cnpj" varchar(18) NOT NULL UNIQUE, 
    "foto_estabelecimento" varchar(255) NULL, 
    "link" varchar(255) NULL, 
    "id_categoria" integer NOT NULL, 
    "id_endereco" integer NOT NULL
);
--
-- Create model Produto
--
CREATE TABLE "AppStoreLink_produto" (
    "id_produto" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, 
    "nome_produto" varchar(100) NOT NULL, 
    "preco" numeric(10, 2) NOT NULL, 
    "descricao" text NULL, 
    "foto" varchar(255) NULL, 
    "id_categoria" integer NOT NULL, 
    "id_loja" integer NOT NULL
);
--
-- Create model Servico
--
CREATE TABLE "AppStoreLink_servico" (
    "id_servico" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, 
    "nome_servico" varchar(100) NOT NULL, 
    "preco" numeric(10, 2) NOT NULL, 
    "descricao" text NULL, 
    "foto" varchar(255) NULL, 
    "id_loja" integer NOT NULL
);
--
-- Create model Usuario
--
CREATE TABLE "AppStoreLink_usuario" (
    "id_categoria" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, 
    "nome" varchar(50) NOT NULL, 
    "sobrenome" varchar(100) NOT NULL, 
    "email" varchar(100) NOT NULL UNIQUE, 
    "senha" varchar(255) NOT NULL, 
    "telefone" varchar(15) NULL, 
    "cpf" varchar(11) NOT NULL UNIQUE, 
    "id_tipo_usuario" integer NOT NULL
);
--
-- Create model Avaliacao
--
CREATE TABLE "AppStoreLink_avaliacao" (
    "id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, 
    "nota" integer NOT NULL, 
    "comentario" text NULL, 
    "id_loja" integer NULL, 
    "id_produto" integer NULL, 
    "id_servico" integer NULL, 
    "id_usuario" integer NOT NULL
);
--
-- Create model LojaFavoritas
--
CREATE TABLE "AppStoreLink_lojafavoritas" (
    "id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, 
    "id_loja" integer NOT NULL, 
    "id_usuario" integer NOT NULL
);

